# Makes the table that the Direct3D 11 backend finds its shaders in: for every shader of code_runtime/source/shaders.inc and smaa.inc that has HLSL
# in code_runtime/source/d3d11, the size and hash of its SPIR-V words (create_shader is given the words and looks the shader up by them), the bytecode
# (the array <name>_dxbc that fxc makes, see code_runtime/CMakeLists.txt, whose headers the output is included after), and what the .d3d11.json says of its
# registers, constants and push constants. The backend reads this table and parses nothing at run time.
#
#   python3 tools/generate_d3d11_table.py <output.inc> [source dir]
import json
import os
import re
import struct
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def modules(source):
    for name in ("shaders.inc", "smaa.inc"):
        text = open(os.path.join(source, name)).read()
        parts = re.split(r"static const unsigned int (\w+)\[\] = \{", text)
        for i in range(1, len(parts), 2):
            words = [int(x, 16) for x in re.findall(r"0x[0-9a-fA-F]+", parts[i + 1].split("};")[0])]
            yield parts[i], struct.pack("<%dI" % len(words), *words)


def fnv1a(data):
    h = 0xCBF29CE484222325
    for b in data:
        h = ((h ^ b) * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
    return h


def constant_bits(kind, default):
    default = default.strip()
    if kind == "bool":
        return 1 if default in ("true", "1") else 0
    if kind == "float":
        return struct.unpack("<I", struct.pack("<f", float(default.rstrip("f"))))[0]
    return int(default.rstrip("u"), 0) & 0xFFFFFFFF


def main():
    output = sys.argv[1]
    source = sys.argv[2] if len(sys.argv) > 2 else os.path.join(ROOT, "code_runtime", "source")
    out = ["// Generated by tools/generate_d3d11_table.py. The bytecode arrays come from the headers of fxc that are included before this.\n"]
    entries = []
    for name, binary in modules(source):
        description = os.path.join(source, "d3d11", name + ".d3d11.json")
        if not os.path.exists(description):
            continue
        d = json.load(open(description))
        stage = "c" if "compute" in name else ("f" if "fragment" in name else "v")
        regs = ", ".join("{%d, %d, '%s', %d}" % (r["set"], r["binding"], r["kind"], r["register"]) for r in d["registers"])
        consts = ", ".join("{%d, '%s', %d, 0x%08Xu}" % (c["id"], c["type"][0], c["offset"], constant_bits(c["type"], c["default"])) for c in d["constants"])
        out.append("static const bb_d3d11_register %s_registers[] = { %s{0, 0, 0, 0} };\n" % (name, regs + ", " if regs else ""))
        out.append("static const bb_d3d11_constant %s_constants[] = { %s{0, 0, 0, 0} };\n" % (name, consts + ", " if consts else ""))
        instance = "BBINSTANCE" in open(os.path.join(source, "d3d11", name + ".hlsl")).read()
        entries.append("\t{ \"%s\", %du, 0x%016Xull, '%s', %s_dxbc, sizeof(%s_dxbc), %s_registers, %d, %s_constants, %d, %d, %d, %s }," % (
            name, len(binary) // 4, fnv1a(binary), stage, name, name, name, len(d["registers"]), name, len(d["constants"]),
            -1 if d["constants_register"] is None else d["constants_register"], -1 if d["push_register"] is None else d["push_register"],
            "true" if instance else "false"))
    out.append("static const bb_d3d11_shader bb_d3d11_shaders[] = {\n" + "\n".join(entries) + "\n};\n")
    with open(output, "w") as f:
        f.write("".join(out))


if __name__ == "__main__":
    main()
